const cfg = $input.first().json;
const p = cfg.body || {};
const LANES = ['critical', 'high', 'normal', 'low'];
const TYPES = ['llm', 'http', 'noop'];
const errors = [];

const type = String(p.type || '').toLowerCase();
if (!TYPES.includes(type)) errors.push('type must be one of ' + TYPES.join(', '));

let lane = 'normal';
if (p.priority !== undefined) {
  const pr = p.priority;
  if (Number.isInteger(pr) && pr >= 0 && pr < LANES.length) lane = LANES[pr];
  else if (LANES.includes(String(pr).toLowerCase())) lane = String(pr).toLowerCase();
  else errors.push('priority must be ' + LANES.join(', ') + ' or 0-3 (0 is highest)');
}

const payload = p.payload && typeof p.payload === 'object' ? p.payload : {};
if (JSON.stringify(payload).length > (Number(cfg.maxPayloadBytes) || 200000)) errors.push('payload is too large');

const delay = Number(p.delaySeconds) || 0;
if (delay < 0 || delay > 604800) errors.push('delaySeconds must be between 0 and 604800');
const maxAttempts = Math.min(10, Math.max(1, Math.floor(Number(p.maxAttempts) || Number(cfg.defaultMaxAttempts) || 3)));

const customId = typeof p.jobId === 'string' && /^[A-Za-z0-9_-]{1,64}$/.test(p.jobId) ? p.jobId : null;
if (typeof p.jobId === 'string' && p.jobId && !customId) errors.push('jobId may only contain letters, numbers, - and _ (max 64)');
const jobId = customId || ('q-' + Date.now() + '-' + Math.random().toString(36).slice(2, 7));

const now = new Date();
const delayed = delay > 0;
const runAt = new Date(now.getTime() + delay * 1000).toISOString();
const token = Math.random().toString(36).slice(2, 10) + Math.random().toString(36).slice(2, 6);

const record = {
  jobId, type, payload, priority: lane, lane,
  status: delayed ? 'scheduled' : 'queued', attempts: 0, maxAttempts, token,
  enqueuedAt: now.toISOString(), runAt, startedAt: null, leaseUntil: null, workerId: null, result: null, error: null,
  history: [{ ts: now.toISOString(), event: delayed ? 'scheduled' : 'enqueued', lane }]
};

return [{ json: {
  valid: errors.length === 0, validationError: errors.join('; '),
  jobId, recordKey: 'job:' + jobId, recordJson: JSON.stringify(record), ttl: Number(cfg.retentionSeconds) || 604800,
  delayed, laneList: 'queue:' + lane,
  message: JSON.stringify({ jobId, token }),
  scheduledEntry: JSON.stringify({ jobId, token, runAt }),
  notifyChannel: cfg.notifyChannel,
  accepted: { jobId, status: record.status, lane, runAt: delayed ? runAt : null, maxAttempts }
} }];

const v = $('Validate Job Configuration').first().json;
const out = $input.first().json;
let ex = null;
if (out.existing) { try { ex = typeof out.existing === 'string' ? JSON.parse(out.existing) : out.existing; } catch (e) { ex = null; } }
return [{ json: { isNew: !ex, duplicateResponse: ex ? { jobId: v.jobId, duplicate: true, status: ex.status, lane: ex.lane } : null } }];

const q = $input.first().json.query || {};
const jobId = typeof q.jobId === 'string' ? q.jobId.trim() : '';
return [{ json: { hasJobId: !!jobId, jobId } }];

const out = $input.first().json;
let rec = null;
if (out.record) { try { rec = typeof out.record === 'string' ? JSON.parse(out.record) : out.record; } catch (e) { rec = null; } }
return [{ json: { response: rec ? rec : { error: 'Job not found (it may have expired)' } } }];

const labels = $('Compile Stats Lists').all().map(i => i.json.label);
const outs = $input.all();
const n = o => { const v = Object.values(o.json || {}).find(x => /^\d+$/.test(String(x))); return v === undefined ? 0 : Number(v); };
const counts = {};
labels.forEach((l, i) => { counts[l] = n(outs[i]); });
const lanes = { critical: counts.critical, high: counts.high, normal: counts.normal, low: counts.low };
return [{ json: { response: {
  lanes, totalQueued: lanes.critical + lanes.high + lanes.normal + lanes.low,
  scheduled: counts.scheduled, processing: counts.processing, deadLetter: counts.dead, generatedAt: new Date().toISOString()
} } }];

const p = $input.first().json.body || {};
const jobId = typeof p.jobId === 'string' ? p.jobId.trim() : '';
return [{ json: { valid: !!jobId, jobId, validationError: jobId ? null : 'jobId is required' } }];

const jobId = $('Parse Cancellation Request').first().json.jobId;
const out = $input.first().json;
let rec = null;
if (out.record) { try { rec = typeof out.record === 'string' ? JSON.parse(out.record) : out.record; } catch (e) { rec = null; } }
const ok = !!rec && ['queued', 'scheduled'].includes(rec.status);
if (ok) { rec.status = 'cancelled'; rec.history.push({ ts: new Date().toISOString(), event: 'cancelled' }); }
const response = ok ? { jobId, cancelled: true } : { jobId, cancelled: false, reason: !rec ? 'Job not found' : 'Only queued or scheduled jobs can be cancelled (status: ' + rec.status + ')' };
return [{ json: { cancellable: ok, recordKey: 'job:' + jobId, recordJson: JSON.stringify(rec), response } }];

const cfg = $('Set Worker Configuration').first().json;
const out = $input.first().json;
const tickVal = Object.values(out || {}).find(v => /^\d+$/.test(String(v)));
const tick = tickVal === undefined ? 0 : Number(tickVal);

let lanes = String(cfg.laneOrder).split(',').map(s => s.trim()).filter(Boolean);
const every = Number(cfg.agingEvery) || 0;
let aged = false;
// Anti-starvation: every Nth poll the lowest lane gets the first turn
if (every > 0 && tick % every === 0 && lanes.length > 1) { lanes = [lanes[lanes.length - 1], ...lanes.slice(0, -1)]; aged = true; }

return [{ json: { workerId: 'exec-' + $execution.id, lanes, aged, tick, laneIndex: 0, jobsDone: 0, maxJobs: Number(cfg.maxJobsPerRun) || 5 } }];

const s = $('Prepare Lane Pop').first().json;
const out = $input.first().json;
const raw = out.message;
let msg = null;
if (raw !== null && raw !== undefined && raw !== '') { try { msg = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { msg = null; } }
const found = !!(msg && msg.jobId && msg.token);
return [{ json: { ...s, found, jobId: found ? msg.jobId : null, token: found ? msg.token : null, lane: s.lanes[s.laneIndex] } }];

const s = $('Prepare Lane Pop').first().json;
const next = s.laneIndex + 1;
return [{ json: { ...s, laneIndex: next, more: next < s.lanes.length } }];

const s = $('Extract Lane Message').first().json;
const out = $input.first().json;
let rec = null;
if (out.record) { try { rec = typeof out.record === 'string' ? JSON.parse(out.record) : out.record; } catch (e) { rec = null; } }
// Stale, duplicate, cancelled or already-claimed messages fail this check
const valid = !!rec && rec.status === 'queued' && rec.token === s.token;
return [{ json: { ...s, record: rec, valid } }];

const v = $input.first().json;
const cfg = $('Set Worker Configuration').first().json;
const now = Date.now();
const rec = JSON.parse(JSON.stringify(v.record));
rec.status = 'processing';
rec.attempts = (rec.attempts || 0) + 1;
rec.startedAt = new Date(now).toISOString();
rec.leaseUntil = new Date(now + (Number(cfg.leaseSeconds) || 300) * 1000).toISOString();
rec.workerId = v.workerId;
rec.history.push({ ts: rec.startedAt, event: 'claimed', attempt: rec.attempts, worker: v.workerId });
return [{ json: {
  ...v, record: rec, recordKey: 'job:' + rec.jobId, recordJson: JSON.stringify(rec), ttl: Number(cfg.retentionSeconds) || 604800,
  processingEntry: JSON.stringify({ jobId: rec.jobId, token: rec.token, claimedAt: rec.startedAt })
} }];

const c = $('Prepare Claim Writes').first().json;
const cfg = $('Set Worker Configuration').first().json;
const rec = c.record;
const pl = rec.payload || {};
let typeAction = 'invalid', llmRequest = null, httpReq = null, prepError = null, prepPermanent = false;

if (rec.type === 'llm') {
  if (!pl.prompt || typeof pl.prompt !== 'string') { prepError = 'llm job needs payload.prompt (string)'; prepPermanent = true; }
  else {
    let catalog = [];
    try { catalog = JSON.parse(cfg.modelCatalog); } catch (e) {}
    const model = catalog.some(m => m.id === pl.model) ? pl.model : cfg.defaultModel;
    typeAction = 'llm';
    llmRequest = { model, max_tokens: Math.min(4096, Math.max(100, Number(pl.maxTokens) || 1000)), messages: [{ role: 'user', content: pl.prompt }] };
    if (pl.system) llmRequest.system = String(pl.system);
  }
} else if (rec.type === 'http') {
  try {
    const u = new URL(String(pl.url));
    const hosts = String(cfg.allowedHttpHosts).split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
    const method = String(pl.method || 'GET').toUpperCase();
    if (u.protocol !== 'https:') throw new Error('only https URLs are allowed');
    if (!hosts.includes(u.hostname.toLowerCase())) throw new Error('host not in allowedHttpHosts: ' + u.hostname);
    if (!['GET', 'POST'].includes(method)) throw new Error('method must be GET or POST');
    typeAction = 'http';
    httpReq = { url: u.toString(), method, body: pl.body || {} };
  } catch (e) { prepError = 'Rejected http job: ' + e.message; prepPermanent = true; }
} else if (rec.type === 'noop') {
  typeAction = 'noop';
} else { prepError = 'Unknown job type: ' + rec.type; prepPermanent = true; }

return [{ json: { ...c, typeAction, llmRequest, httpReq, prepError, prepPermanent, anthropicApiUrl: cfg.anthropicApiUrl } }];

const ctx = $('Prepare Job Execution').first().json;
const cfg = $('Set Worker Configuration').first().json;
const resp = $input.first().json;
const rec = JSON.parse(JSON.stringify(ctx.record));
const now = new Date();

let ok = false, result = null, error = null, permanent = false, cost = 0;
if (ctx.typeAction === 'llm') {
  const text = Array.isArray(resp.content) ? resp.content.filter(b => b.type === 'text').map(b => b.text).join('\n').trim() : '';
  ok = !resp.error && !!text;
  if (ok) {
    let catalog = [];
    try { catalog = JSON.parse(cfg.modelCatalog); } catch (e) {}
    const m = catalog.find(x => x.id === ctx.llmRequest.model) || { inputPer1M: 0, outputPer1M: 0 };
    const u = resp.usage || {};
    cost = (u.input_tokens || 0) / 1e6 * m.inputPer1M + (u.output_tokens || 0) / 1e6 * m.outputPer1M;
    result = { text: text.slice(0, 8000), model: ctx.llmRequest.model, costUsd: Math.round(cost * 1e6) / 1e6 };
  } else {
    error = resp.error ? String(resp.error.message || JSON.stringify(resp.error)).slice(0, 300) : 'empty response';
    const t = resp.error && resp.error.type;
    permanent = t === 'invalid_request_error' || t === 'authentication_error' || t === 'permission_error';
  }
} else if (ctx.typeAction === 'http') {
  const sc = Number(resp.statusCode);
  if (resp.error || !sc) { error = String((resp.error && resp.error.message) || 'request failed').slice(0, 300); }
  else {
    ok = sc >= 200 && sc < 300;
    const body = typeof resp.body === 'string' ? resp.body : JSON.stringify(resp.body);
    result = { statusCode: sc, body: String(body).slice(0, 8000) };
    if (!ok) { error = 'HTTP ' + sc; permanent = sc >= 400 && sc < 500 && sc !== 408 && sc !== 429; }
  }
} else if (ctx.typeAction === 'noop') {
  ok = true; result = { echo: rec.payload };
} else { error = ctx.prepError; permanent = !!ctx.prepPermanent; }

let outcome, scheduledEntry = null, deadEntry = null;
if (ok) {
  outcome = 'completed';
  rec.status = 'completed'; rec.result = result; rec.error = null; rec.finishedAt = now.toISOString(); rec.leaseUntil = null;
  rec.history.push({ ts: rec.finishedAt, event: 'completed', attempt: rec.attempts });
} else if (permanent || rec.attempts >= rec.maxAttempts) {
  outcome = 'dead';
  rec.status = 'dead'; rec.error = error; rec.finishedAt = now.toISOString(); rec.leaseUntil = null;
  rec.history.push({ ts: rec.finishedAt, event: 'dead_lettered', attempt: rec.attempts, error });
  deadEntry = JSON.stringify({ jobId: rec.jobId, type: rec.type, error, attempts: rec.attempts, ts: rec.finishedAt });
} else {
  outcome = 'retry';
  const base = Number(cfg.backoffBaseSeconds) || 15, max = Number(cfg.backoffMaxSeconds) || 900;
  const delay = Math.min(max, base * Math.pow(2, rec.attempts - 1)) * (1 + Math.random() * 0.2);
  rec.status = 'scheduled'; rec.runAt = new Date(now.getTime() + delay * 1000).toISOString();
  rec.token = Math.random().toString(36).slice(2, 10) + Math.random().toString(36).slice(2, 6);  // invalidates old messages
  rec.error = error; rec.leaseUntil = null; rec.workerId = null;
  rec.history.push({ ts: now.toISOString(), event: 'retry_scheduled', attempt: rec.attempts, error, runAt: rec.runAt });
  scheduledEntry = JSON.stringify({ jobId: rec.jobId, token: rec.token, runAt: rec.runAt });
}
return [{ json: { ...ctx, outcome, finalRecord: rec, scheduledEntry, deadEntry } }];

const r = $('Store Job Result').first().json;
const out = $input.first().json;
let cur = null;
if (out.record) { try { cur = typeof out.record === 'string' ? JSON.parse(out.record) : out.record; } catch (e) { cur = null; } }
// Only the worker that still owns the lease may write the outcome (a reaper may have requeued the job)
const held = !!cur && cur.status === 'processing' && cur.token === r.record.token && cur.workerId === r.workerId;
return [{ json: { held, outcome: r.outcome, recordKey: 'job:' + r.jobId, recordJson: JSON.stringify(r.finalRecord), ttl: Number(($('Set Worker Configuration').first().json).retentionSeconds) || 604800, scheduledEntry: r.scheduledEntry, deadEntry: r.deadEntry } }];

const s = $('Prepare Lane Pop').first().json;
const done = (s.jobsDone || 0) + 1;
// After each message, restart from the highest priority lane
return [{ json: { ...s, jobsDone: done, laneIndex: 0, continue: done < s.maxJobs } }];

const s = $('Prepare Maint Pop').first().json;
const raw = $input.first().json.entry;
let entry = null;
if (raw !== null && raw !== undefined && raw !== '') { try { entry = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { entry = null; } }
const found = !!(entry && entry.jobId && entry.token);
const key = found ? entry.jobId + ':' + entry.token : null;
return [{ json: { ...s, found, entry, key, repeat: found && !!s.seen[key] } }];

const s = $('Parse Maint Entry').first().json;
const out = $input.first().json;
const task = s.tasks[s.taskIndex];
let rec = null;
if (out.record) { try { rec = typeof out.record === 'string' ? JSON.parse(out.record) : out.record; } catch (e) { rec = null; } }
const now = Date.now();
const nowIso = new Date(now).toISOString();
const entryJson = JSON.stringify(s.entry);

let action = 'drop', endTask = false, deadEntry = null;
if (s.repeat) { action = 'rotate_back'; endTask = true; }   // completed a full cycle of this list
else if (task === 'scheduled') {
  if (!rec || rec.status !== 'scheduled' || rec.token !== s.entry.token) action = 'drop';
  else if (new Date(rec.runAt).getTime() <= now) { action = 'enqueue'; rec.status = 'queued'; rec.history.push({ ts: nowIso, event: 'promoted' }); }
  else action = 'rotate_back';
} else {
  if (!rec || rec.status !== 'processing' || rec.token !== s.entry.token) action = 'drop';   // finished or superseded
  else if (new Date(rec.leaseUntil).getTime() < now) {
    if (rec.attempts >= rec.maxAttempts) {
      action = 'dead'; rec.status = 'dead'; rec.error = 'Lease expired after max attempts'; rec.leaseUntil = null;
      rec.history.push({ ts: nowIso, event: 'dead_lettered', error: rec.error });
      deadEntry = JSON.stringify({ jobId: rec.jobId, type: rec.type, error: rec.error, attempts: rec.attempts, ts: nowIso });
    } else {
      action = 'enqueue'; rec.status = 'queued'; rec.workerId = null; rec.leaseUntil = null;
      rec.token = Math.random().toString(36).slice(2, 10) + Math.random().toString(36).slice(2, 6);
      rec.history.push({ ts: nowIso, event: 'lease_expired_requeued', attempt: rec.attempts });
    }
  } else action = 'rotate_back';
}
return [{ json: {
  action, endTask, entryList: 'queue:' + task, entryJson,
  recordKey: rec ? 'job:' + rec.jobId : null, recordJson: rec ? JSON.stringify(rec) : null, ttl: s.ttl,
  laneList: rec ? 'queue:' + rec.lane : null, laneMessage: rec ? JSON.stringify({ jobId: rec.jobId, token: rec.token }) : null,
  deadEntry, notifyChannel: s.notifyChannel, jobId: rec ? rec.jobId : null
} }];

const s = $('Parse Maint Entry').first().json;
const dec = s.found ? $('Decide Maintenance').first().json : null;
let taskIndex = s.taskIndex, processed = s.processed;
let seen = { ...s.seen };
if (s.found) { seen[s.key] = true; processed += 1; }
const endTask = !s.found || (dec && dec.endTask) || processed >= s.batch;
if (endTask) { taskIndex += 1; processed = 0; seen = {}; }
return [{ json: { tasks: s.tasks, taskIndex, processed, batch: s.batch, seen, ttl: s.ttl, notifyChannel: s.notifyChannel, continue: taskIndex < s.tasks.length } }];
